code.source:
#include <stdio.h>

int main(void) {
    char town[] = "Mapusa";
    const char *beach = "Baga";

    printf("%s and %s\n", town, beach);

    town[0] = 'm';
    printf("Changed: %s\n", town);

    const char *p = beach;
    while (*p != '\0') {
        printf("%c-", *p);
        p++;
    }
    printf("\n");

    printf("sizeof town = %zu, sizeof beach = %zu\n", sizeof town, sizeof beach);
    return 0;
}

